export const PET_NATURE_EFFECTS=Object.freeze({meleeAttack:.02,rangedAttack:.02,magicAttack:.02,meleeHit:1,rangedHit:1,dg:1,ac:-.5,mr:1,attackSpeed:.02,moveSpeed:.02,hpRegen:.05,mpRegen:.025,hpGrowth:.01,mpGrowth:.01});
