  maxHp:adjust('maxHp',Math.floor((def.stats.level1_hp+level*def.growth.hp_per_level*(1+nature.hpGrowth))*factor('VIT'))),
  maxMp:adjust('maxMp',Math.floor((def.stats.level1_mp+level*(def.growth.mp_per_level||0)*(1+nature.mpGrowth))*factor('MND'))),
  attack:adjust('attack',Math.floor((def.stats.base_attack+.5*level)*factor('STR'))),
  ac:adjust('ac',8-Math.floor(level/5)-Math.floor(4*(q('VIT')-.5))),
  mr:adjust('mr',clamp(def.stats.mr+4*(q('MND')-.5),0,100)),
