export function validatePetBreeding(s){const errors=[],check=(ok,message)=>{if(!ok)errors.push(message)},dec=value=>typeof value==='string'&&/^(0|[1-9]\d*)$/.test(value);try{const ledger=s.petBreeding;if(ledger===undefined)return{ok:true,errors};check(ledger.version===1&&dec(ledger.next)&&dec(ledger.applied)&&Array.isArray(ledger.receipts)&&ledger.receipts.length<=32,'繁殖帳本');check(BigInt(ledger.next)===BigInt(ledger.applied)+(ledger.pending?2n:1n),'繁殖序號');if(ledger.pending){const pending=ledger.pending;check(dec(pending.id)&&BigInt(pending.id)===BigInt(ledger.applied)+1n,'繁殖預備序號');check(Array.isArray(pending.parents)&&pending.parents.length===2&&pending.parents[0].id!==pending.parents[1].id,'繁殖親代');for(const parent of pending.parents){const pet=s.pets.find(pet=>pet.id===parent.id);check(pet&&pet.collarUid===parent.collarUid&&pet.v4?.lineage.id===parent.lineageId&&pet.v4?.breedingUsed===parent.used,'繁殖親代已變更')}const child=pending.child;check(child?.sourceKind==='bred'&&child.level===1&&child.active===false&&child.dead===false&&child.v4?.breedingUsed===0&&validatePetV4(child).ok,'繁殖子代');check(!s.pets.some(pet=>pet.id===child.id||pet.collarUid===child.collarUid),'繁殖子代身分重複')};const ids=new Set;for(const receipt of ledger.receipts){check(dec(receipt.id)&&BigInt(receipt.id)>0n&&BigInt(receipt.id)<=BigInt(ledger.applied)&&!ids.has(receipt.id)&&typeof receipt.childId==='string'&&typeof receipt.lineageId==='string'&&typeof receipt.shiny==='boolean'&&typeof receipt.ancestral==='boolean','繁殖收據');ids.add(receipt.id)}}catch{errors.push('繁殖帳本結構損壞')}return{ok:errors.length===0,errors}}

export function petAuraModifiers(s,actor=s.player){const active=new Set;for(const pet of s.pets){if(!pet.v4||!pet.active||pet.dead||pet.hp<=0||pet.food<=0||pet.overCapacity||pet.level>s.player.level||pet.map!==actor.map||Math.max(Math.abs(pet.x-actor.x),Math.abs(pet.y-actor.y))>5)continue;for(const key of PET_ATTRIBUTES)if(attributeQuality(pet.type,key,pet.v4.birth[key])==='orange')active.add(key)}return{physical:active.has('STR')?1.01:1,magic:active.has('INT')?1.01:1,attackSpeed:active.has('DEX')?1.01:1,moveSpeed:active.has('DEX')?1.01:1,mr:active.has('MND')?1:0,maxHp:active.has('VIT')?1.01:1}}
